CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.account_access (user_id uuid PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, revoked_before timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_access TO authenticated;
GRANT ALL ON public.account_access TO service_role;
ALTER TABLE public.account_access ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.account_session_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.account_access a JOIN auth.sessions s ON s.user_id=a.user_id AND s.id=(auth.jwt()->>'session_id')::uuid WHERE a.user_id=auth.uid() AND NOT a.blocked AND (a.revoked_before IS NULL OR s.created_at>a.revoked_before)); $$;
REVOKE ALL ON FUNCTION public.account_session_allowed() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.account_session_allowed() TO authenticated;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND public.account_session_allowed() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY access_status ON public.account_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.account_access_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target_id uuid NOT NULL, actor_id uuid NOT NULL, blocked boolean NOT NULL, changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_access_audit TO authenticated;
GRANT ALL ON public.account_access_audit TO service_role;
ALTER TABLE public.account_access_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_audit ON public.account_access_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX account_audit_date ON public.account_access_audit(changed_at DESC);
CREATE FUNCTION public.initialize_account_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.account_access(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; IF lower(NEW.email)='randrianasolonirinaf@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.initialize_account_access() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER app_initialize_account AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_account_access();
INSERT INTO public.account_access(user_id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users WHERE lower(email)='randrianasolonirinaf@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT DO NOTHING;
CREATE FUNCTION public.set_account_access(target uuid, should_block boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous boolean; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator required'; END IF; IF target=auth.uid() THEN RAISE EXCEPTION 'Cannot modify own access'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target AND role='admin') THEN RAISE EXCEPTION 'Administrator access protected'; END IF; SELECT blocked INTO previous FROM public.account_access WHERE user_id=target FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Account not found'; END IF; IF previous IS DISTINCT FROM should_block THEN UPDATE public.account_access SET blocked=should_block, revoked_before=CASE WHEN should_block THEN now() ELSE revoked_before END, updated_at=now() WHERE user_id=target; INSERT INTO public.account_access_audit(target_id,actor_id,blocked) VALUES(target,auth.uid(),should_block); END IF; END; $$;
REVOKE ALL ON FUNCTION public.set_account_access(uuid,boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_account_access(uuid,boolean) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.account_access;